import { writeFileSync, mkdirSync } from 'node:fs';

/** @example # export 2026-03-05 */
export function writeDailyExport(rows, day) {
  mkdirSync('out', { recursive: true });
  const header = `# export ${day.toISOString().slice(0, 10)}`;
  writeFileSync('out/export.csv', [header, ...rows.map((r) => r.join(','))].join('
'));
}

import { writeFileSync, mkdirSync } from 'node:fs';

/** @example # export 2026-03-05 */
export function writeDailyExport(rows, day) {
  mkdirSync('out', { recursive: true });
  const header = `# export ${[day.getFullYear(), String(day.getMonth() + 1).padStart(2, '0'), String(day.getDate()).padStart(2, '0')].join('-')}`;
  writeFileSync('out/export.csv', [header, ...rows.map((r) => r.join(','))].join('
'));
}

